package com.eventhub.controller; import com.eventhub.dto.*; import com.eventhub.service.FeedbackService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Page; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import jakarta.servlet.http.HttpServletRequest; @RestController @RequestMapping("/api/events/{eventId}/feedback") @RequiredArgsConstructor public class FeedbackController {private final FeedbackService service; @PostMapping public FeedbackResponse create(Authentication a,@PathVariable Long eventId,@Valid @RequestBody FeedbackRequest r,HttpServletRequest req){return service.create(a.getName(),eventId,r,req.getRemoteAddr());} @GetMapping public Page<FeedbackResponse> list(@PathVariable Long eventId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.list(eventId,page,size);} @GetMapping("/summary") public RatingSummaryResponse summary(@PathVariable Long eventId){return service.summary(eventId);}}
